<?php
declare(strict_types=1);
require __DIR__ . '/config.php';require __DIR__ . '/helpers.php';
$profile=business_profile($pdo);$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);try{$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$amount=filter_var(str_replace(',','.',(string)($_POST['amount']??'')),FILTER_VALIDATE_FLOAT);$date=(string)($_POST['expense_date']??date('Y-m-d'));if($title===''||$amount===false||$amount<=0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Gider bilgileri geçersiz.');if(text_length($title)>160||text_length($description)>500)throw new RuntimeException('Başlık veya açıklama çok uzun.');$stmt=$pdo->prepare('INSERT INTO expenses(title,description,amount,expense_date) VALUES(?,?,?,?)');$stmt->execute([$title,$description!==''?$description:null,$amount,$date]);$message='Gider kaydedildi.';}catch(Throwable $e){$error=$e->getMessage();}}
$todayTotal=active_expense_total($pdo);$todayRows=$pdo->query("SELECT * FROM expenses WHERE expense_date=CURDATE() AND day_end_report_id IS NULL ORDER BY id DESC LIMIT 20")->fetchAll();$csrf=csrf_token();
?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gider Ekle • <?= e($profile['name']) ?></title><?php if($profile['logo_path']!==''):?><link rel="icon" href="<?= e($profile['logo_path']) ?>"><?php endif;?>
    <link rel="stylesheet" href="assets/style.css?v=10.1"></head><body><header class="topbar"><div class="container topbar-inner"><a class="brand" href="home.php"><?php if($profile['logo_path']!==''):?><span class="brand-mark brand-mark-image"><img src="<?= e($profile['logo_path']) ?>" alt="Logo"></span><?php else:?><span class="brand-mark"><?= e(business_initials($profile['name'])) ?></span><?php endif;?><span><?= e($profile['name']) ?><small>Hızlı Gider Girişi</small></span></a><div class="nav-actions"><a class="btn btn-ghost" href="home.php">← Ana Ekran</a><a class="btn btn-ghost" href="orders.php">Adisyonlar</a><a class="btn" href="admin/expenses.php">Gider Geçmişi</a></div></div></header><main class="standalone-page container"><section class="admin-heading"><div><div class="eyebrow">Günlük Operasyon</div><h1 class="admin-title">Gider ekle</h1><p class="muted">Personel ana ekrandan hızlıca gider kaydedebilir. Eski kayıtların düzenleme ve silme işlemleri admin panelindedir.</p></div><div class="finance-card highlight mini-finance"><span>Bugünkü gider</span><strong><?= money($todayTotal) ?></strong></div></section><?php if($message):?><div class="alert alert-success"><?= e($message) ?></div><?php endif;?><?php if($error):?><div class="alert alert-error"><?= e($error) ?></div><?php endif;?><section class="dashboard-grid expenses-layout"><div class="panel"><div class="panel-title"><div><div class="eyebrow">Yeni Gider</div><h2>Gider bilgisi</h2></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><label>Başlık<input name="title" required placeholder="Örn. Market alışverişi"></label><label>Kısa bilgi<textarea name="description" placeholder="İsteğe bağlı açıklama"></textarea></label><div class="form-row"><label>Tutar (₺)<input type="number" min="0.01" step="0.01" name="amount" required></label><label>Tarih<input type="date" name="expense_date" value="<?= e(date('Y-m-d')) ?>" required></label></div><button class="btn btn-primary btn-lg" type="submit">Gideri Kaydet</button></form></div><div class="panel"><div class="panel-title"><div><div class="eyebrow">Bugün</div><h2>Son giderler</h2></div></div><?php if(!$todayRows):?><p class="muted">Bugün gider girilmedi.</p><?php else:?><div class="simple-list"><?php foreach($todayRows as $r):?><div><span><strong><?= e($r['title']) ?></strong><small><?= e((string)($r['description']??'')) ?></small></span><b><?= money((float)$r['amount']) ?></b></div><?php endforeach;?></div><?php endif;?></div></section></main><script src="assets/app.js?v=10"></script></body></html>
